            neighbors = [grid[rr][cc]
                         for rr in range(max(0,r-1), min(h,r+2))
                         for cc in range(max(0,c-1), min(w,c+2))
                         if (rr,cc) != (r,c)]
            counts = {v: neighbors.count(v) for v in set(neighbors) if v}
