            if not connected:
                clean[r][c] = 0

    markers = []
    for r in range(h):
        for c in range(w):
            if clean[r][c]:
                continue
            counts = {color: 0 for color in colors}
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    rr, cc = r + dr, c + dc
